# Perbaikan Viti Shopkeepers, pemisahan chat RP, dan gerakan teks /me /do.
# Membuat backup source; tidak mengubah setup dungeon atau NPC.
[CmdletBinding()]
param([switch]$CheckOnly)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$root = [System.IO.Path]::GetFullPath($PSScriptRoot)
$utf8 = New-Object System.Text.UTF8Encoding($false)
if (-not (Test-Path -LiteralPath (Join-Path $root 'gradlew.bat') -PathType Leaf)) {
    throw 'Letakkan install-viti-roleplay-fix.ps1 sejajar dengan gradlew.bat di folder project vitaemanager.'
}
function Get-SourceHash([byte[]]$Bytes) {
    $text = $utf8.GetString($Bytes).TrimStart([char]0xFEFF).Replace("`r`n", "`n").Replace("`r", "`n").TrimEnd([char]10) + "`n"
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { return [System.BitConverter]::ToString($sha.ComputeHash($utf8.GetBytes($text))).Replace('-', '').ToLowerInvariant() }
    finally { $sha.Dispose() }
}
$files = @(
    [pscustomobject]@{ Path = 'src/main/java/com/bangzachery/vitae/vitaemanager/economy/VitiPaper.java'; Before = '55186b8e25dcf836965220476e3551bfed11917d61025439d63b4ad5abb0a48a'; After = 'a383a751f92982795ee57e0d4922bc369e14584804172473df60d20b0bbc98d6'; Content = '' },
    [pscustomobject]@{ Path = 'src/main/java/com/bangzachery/vitae/vitaemanager/economy/VitiLedger.java'; Before = '243238ce4f9c2824cfd431fdbfd55578eeac2579182df767c3e2a4bdbfcece26'; After = '907c0c22a3c256a81bfd9577cff445d234f68ac8f3789c842c9ce6231b397f15'; Content = '' },
    [pscustomobject]@{ Path = 'src/main/java/com/bangzachery/vitae/vitaemanager/economy/VitiService.java'; Before = '2680cd8ee7baeeebee94f3a8f56f67964cee2aacc28531cd2ded546b4a1cabf0'; After = '60e55fcb39520ea0875fd4980f6e78beec6c42005ed42487c2b336b6d9f009e3'; Content = '' },
    [pscustomobject]@{ Path = 'src/main/java/com/bangzachery/vitae/vitaemanager/economy/VitiListener.java'; Before = 'fc64c107f0baadcc0a7d1175a9df7f3345d245fc5d7837a14c142eba23637582'; After = 'a60ad129a3924db0ddfcf08721926197eece2150a78972d9ebf6b693d3b366ce'; Content = '' },
    [pscustomobject]@{ Path = 'src/main/java/com/bangzachery/vitae/vitaemanager/economy/VitiShopkeepers.java'; Before = 'ABSENT'; After = '9014af004c168fc9a46292e1ab29bb2d7431740cee110283efdd6ca8d8d5c3cd'; Content = '' },
    [pscustomobject]@{ Path = 'src/main/java/com/bangzachery/vitae/vitaemanager/command/RoleplayCommand.java'; Before = 'b617077a4e401e0456bf0883d9c84cc05369aa93efe82e2aaf3d793d89325dd5'; After = 'e8a2f6842035c60f2d0a7ed801349ca14486956d33c6996abcf72f226fb7cbfe'; Content = '' },
    [pscustomobject]@{ Path = 'src/main/java/com/bangzachery/vitae/vitaemanager/roleplay/RoleplayService.java'; Before = '73a5ff7883879b8560f40d05a21f41d8b34f6d52cf31402bd79a083e51f03fe7'; After = '843b3e350b6d6d897f490aceb68f172ad869550d3737e37caf65f69917f5d63d'; Content = '' }
)
$changes = New-Object 'System.Collections.Generic.List[object]'
foreach ($entry in $files) {
    $target = Join-Path $root $entry.Path
    $exists = Test-Path -LiteralPath $target -PathType Leaf
    if ($exists) {
        $currentHash = Get-SourceHash ([System.IO.File]::ReadAllBytes($target))
        if ($currentHash -eq $entry.After) { Write-Host ('Sudah terbaru: ' + $entry.Path) -ForegroundColor Green; continue }
        if ($entry.Before -eq 'ABSENT' -or $currentHash -ne $entry.Before) {
            throw ('Versi source berbeda: ' + $entry.Path + '. Belum ada file yang diganti. Kirim file tersebut agar pembaruan disesuaikan dengan source terbaru kamu.')
        }
    } elseif ($entry.Before -ne 'ABSENT') {
        throw ('Source belum ada: ' + $entry.Path + '. Belum ada file yang diganti.')
    }
    $payload = [System.Convert]::FromBase64String($entry.Content)
    if ((Get-SourceHash $payload) -ne $entry.After) { throw ('Isi installer tidak valid: ' + $entry.Path) }
    $changes.Add($entry)
    Write-Host ('Siap diperbarui: ' + $entry.Path) -ForegroundColor Cyan
}
if ($CheckOnly) { Write-Host 'Pemeriksaan selesai. Belum ada file yang diganti.' -ForegroundColor Green; return }
if ($changes.Count -eq 0) { Write-Host 'Perbaikan sudah terpasang.' -ForegroundColor Green; return }
$backup = Join-Path $root ('viti-roleplay-backup-' + (Get-Date -Format 'yyyyMMdd-HHmmss-fff'))
New-Item -ItemType Directory -Path $backup | Out-Null
foreach ($entry in $files) {
    $source = Join-Path $root $entry.Path
    if (-not (Test-Path -LiteralPath $source -PathType Leaf)) { continue }
    $destination = Join-Path $backup $entry.Path
    New-Item -ItemType Directory -Path ([System.IO.Path]::GetDirectoryName($destination)) -Force | Out-Null
    Copy-Item -LiteralPath $source -Destination $destination
}
$temporary = New-Object 'System.Collections.Generic.List[string]'
try {
    foreach ($entry in $changes) {
        $target = Join-Path $root $entry.Path
        New-Item -ItemType Directory -Path ([System.IO.Path]::GetDirectoryName($target)) -Force | Out-Null
        $stage = Join-Path ([System.IO.Path]::GetDirectoryName($target)) ([System.IO.Path]::GetRandomFileName())
        $temporary.Add($stage)
        [System.IO.File]::WriteAllBytes($stage, [System.Convert]::FromBase64String($entry.Content))
        Move-Item -LiteralPath $stage -Destination $target -Force
        if ((Get-SourceHash ([System.IO.File]::ReadAllBytes($target))) -ne $entry.After) { throw ('Verifikasi gagal: ' + $entry.Path) }
    }
} catch {
    $failure = $_
    foreach ($entry in $changes) {
        $saved = Join-Path $backup $entry.Path
        $target = Join-Path $root $entry.Path
        try {
            if (Test-Path -LiteralPath $saved -PathType Leaf) { Copy-Item -LiteralPath $saved -Destination $target -Force }
            elseif ($entry.Before -eq 'ABSENT' -and (Test-Path -LiteralPath $target -PathType Leaf)) { Remove-Item -LiteralPath $target -Force }
        } catch { Write-Warning ('Pulihkan manual dari backup: ' + $entry.Path) }
    }
    throw $failure
} finally {
    foreach ($stage in $temporary) { if (Test-Path -LiteralPath $stage) { Remove-Item -LiteralPath $stage -Force } }
}
Write-Host ''
Write-Host 'Perbaikan berhasil dipasang. Setup dungeon dan NPC tetap dipakai.' -ForegroundColor Green
Write-Host ('Backup source: ' + $backup)
Write-Host 'Build tanpa test: .\gradlew.bat clean build -x test'
Write-Host 'Ganti JAR saat server berhenti. Pertahankan folder plugins/vitaemanager dan plugins/Shopkeepers.'
Write-Host 'Shopkeepers: use-strict-item-comparison harus false. Nominal dan serial diperiksa Vitaemanager.'
Write-Host 'Harga Viti disesuaikan saat toko dibuka; cukup tutup dan buka kembali GUI toko.'
